DE7 = {
"A command still running after this is given up on. The tray menu can stop one earlier.": "Ein Befehl, der danach noch läuft, wird aufgegeben. Das Tray-Menü kann einen früher stoppen.",
"A meeting is recorded from two devices at once: your microphone and whatever comes out of your speakers. Nothing has to guess who was speaking, because the two never share a channel.": "Ein Meeting wird von zwei Geräten gleichzeitig aufgezeichnet: Ihrem Mikrofon und allem, was aus Ihren Lautsprechern kommt. Nichts muss raten, wer gesprochen hat, weil die beiden nie denselben Kanal teilen.",
"A name like “sonnet” always means the newest model of that line. Opus thinks harder and answers slower, which is felt here more than anywhere else: you are standing in front of the screen.": "Ein Name wie „sonnet“ meint immer das neueste Modell dieser Reihe. Opus denkt härter und antwortet langsamer, was sich hier stärker bemerkbar macht als anderswo: Sie stehen vor dem Bildschirm.",
"A run that fails keeps its recording either way, so it can be tried again from the Meeting tab. This is about the ones that worked.": "Ein fehlgeschlagener Lauf behält seine Aufnahme ohnehin, sodass er im Meeting-Tab erneut versucht werden kann. Hier geht es um die, die funktioniert haben.",
"Academic English": "Akademisches Englisch",
"Add an API key to use cloud models.": "Fügen Sie einen API-Schlüssel hinzu, um Cloud-Modelle zu nutzen.",
"Add files…": "Dateien hinzufügen…",
"Already reading…": "Liest bereits…",
"Audio export failed: {error}": "Audio-Export fehlgeschlagen: {error}",
"Audio files": "Audiodateien",
"Audio files saved from this tab.": "Audiodateien, die in diesem Tab gespeichert wurden.",
"Audio output timed out.": "Zeitüberschreitung bei der Audioausgabe.",
"Audio stays on this computer. Cleanup is off; the raw transcript is used.": "Audio bleibt auf diesem Computer. Bereinigung ist aus; das Rohtranskript wird verwendet.",
"Audio stays on this computer. Cleanup sends the text to Gemini when enabled.": "Audio bleibt auf diesem Computer. Die Bereinigung sendet den Text an Gemini, wenn sie aktiviert ist.",
"Automatic uses the Nvidia GPU when its driver and CUDA runtime answer, otherwise the CPU. Forcing Nvidia GPU fails with a clear message when CUDA is missing instead of silently using the CPU.": "Automatisch nutzt die Nvidia-GPU, wenn Treiber und CUDA-Runtime antworten, sonst die CPU. Erzwungenes Nvidia-GPU schlägt mit einer klaren Meldung fehl, wenn CUDA fehlt, statt still die CPU zu nutzen.",
"Calculating…": "Berechnung…",
"Checking local speech device…": "Lokales Sprachgerät wird geprüft…",
"Clear list": "Liste leeren",
"Commands within this long of each other are one conversation, so “and move that to Thursday” knows what “that” is. After it, the next command starts fresh.": "Befehle, die so kurz hintereinander kommen, sind ein Gespräch, sodass „und verschieb das auf Donnerstag“ weiß, was „das“ ist. Danach beginnt der nächste Befehl von vorn.",
"Connecting…": "Verbinden…",
"Convert all to audio": "Alle in Audio umwandeln",
"Convert to audio and read": "In Audio umwandeln und vorlesen",
"Copied raw, cleanup failed: {error}": "Roh kopiert, Bereinigung fehlgeschlagen: {error}",
"Could not check the local speech device.": "Das lokale Sprachgerät konnte nicht geprüft werden.",
"Could not read the selection.": "Die Auswahl konnte nicht gelesen werden.",
"Could not work out which speaker output to record. Pick one in Settings → Meeting.": "Es ließ sich nicht ermitteln, welche Lautsprecherausgabe aufgezeichnet werden soll. Wählen Sie eine unter Einstellungen → Meeting.",
"Default format": "Standardformat",
"Default speed": "Standardgeschwindigkeit",
"Delete the downloaded {name} model? {size} goes back to the disk. Nothing else is touched.": "Das heruntergeladene Modell {name} löschen? {size} werden auf der Festplatte frei. Sonst wird nichts angefasst.",
"Download stopped. Press Download to resume.": "Download gestoppt. Drücken Sie Download, um fortzufahren.",
"Downloading the Turkish voice model (~34 MB)…": "Türkisches Stimmmodell wird heruntergeladen (~34 MB)…",
"Downloads on first read (~34 MB).": "Wird beim ersten Vorlesen heruntergeladen (~34 MB).",
"Everyone on the far end shares one label: they reach you as a single mixed signal. The names go to the transcription model so they come out spelled right, and to the minutes, which may use one for a line only when the conversation itself makes clear who was speaking.": "Alle auf der Gegenseite teilen ein Label: Bei Ihnen kommen sie als ein einziges gemischtes Signal an. Die Namen gehen an das Transkriptionsmodell, damit sie richtig geschrieben herauskommen, und an das Protokoll, das einen davon für eine Zeile nur dann verwendet, wenn das Gespräch selbst klar macht, wer gesprochen hat.",
"Files": "Dateien",
"Format": "Format",
"GPU support ({size}) is not installed yet. Download it first, then the {name} model? Answering No downloads only the model for CPU use.": "GPU-Unterstützung ({size}) ist noch nicht installiert. Erst herunterladen, dann das Modell {name}? Bei „Nein“ wird nur das Modell für CPU-Nutzung heruntergeladen.",
"GPU support is not downloaded yet. Install it from Settings, Speech to text, or switch the device to Automatic.": "GPU-Unterstützung ist noch nicht heruntergeladen. Installieren Sie sie unter Einstellungen, Sprache zu Text, oder stellen Sie das Gerät auf Automatisch.",
"Game English": "Spiel-Englisch",
"How long a thinking model may reason before it answers. Cleanup is a light job, so more thinking mostly costs time and tokens. Models that cannot think ignore this.": "Wie lange ein denkendes Modell nachdenken darf, bevor es antwortet. Bereinigung ist eine leichte Aufgabe, mehr Nachdenken kostet meist nur Zeit und Tokens. Modelle, die nicht denken können, ignorieren das.",
"How the sound wave is drawn on the recording indicator. Spectrum and Capsules glow as you speak louder; Wave is a single flowing line.": "Wie die Schallwelle in der Aufnahmeanzeige gezeichnet wird. Spectrum und Capsules leuchten, wenn Sie lauter sprechen; Wave ist eine einzelne fließende Linie.",
"Keep audio files (%LOCALAPPDATA%\\WordArc\\recordings)": "Audiodateien behalten (%LOCALAPPDATA%\\WordArc\\recordings)",
"Live uses {model}; it cannot be changed. The model under Transcript cleanup tidies the text afterwards.": "Live verwendet {model}; das lässt sich nicht ändern. Das Modell unter Transkript-Bereinigung räumt den Text danach auf.",
"Local transcribes on this computer and sends no audio anywhere. Cloud and Live use Gemini and need an API key: Cloud types up a recording after it ends, Live streams your speech as you speak and shows the words while you are still talking.": "Local transkribiert auf diesem Computer und sendet kein Audio irgendwohin. Cloud und Live verwenden Gemini und brauchen einen API-Schlüssel: Cloud schreibt eine Aufnahme nach ihrem Ende ab, Live überträgt Ihre Sprache, während Sie sprechen, und zeigt die Wörter, während Sie noch reden.",
"Measured on Turkish dictation. base is quick and the smallest download; small is in between; large-v3-turbo reads hardest audio most reliably and never invents a closing sentence.": "Gemessen bei türkischem Diktat. base ist schnell und der kleinste Download; small liegt dazwischen; large-v3-turbo liest schwierigstes Audio am zuverlässigsten und erfindet nie einen Schlusssatz.",
"Meeting minutes and transcripts are stored as readable text files under %LOCALAPPDATA%\\WordArc\\meetings.": "Meeting-Protokolle und Transkripte werden als lesbare Textdateien unter %LOCALAPPDATA%\\WordArc\\meetings gespeichert.",
"Model download needs huggingface_hub: {error}": "Modell-Download benötigt huggingface_hub: {error}",
"Model ready: {name}": "Modell bereit: {name}",
"Model status": "Modellstatus",
"More thinking is slower, and you are standing in front of the screen while it happens. Worth it for a job that has to be worked out rather than looked up.": "Mehr Nachdenken ist langsamer, und Sie stehen währenddessen vor dem Bildschirm. Lohnt sich für eine Aufgabe, die durchdacht statt nachgeschlagen werden muss.",
"Names and terms you say often (optional). They go to the transcription model as a hint, and to the cleanup model as a glossary, so it can repair the ones that still come out wrong.": "Namen und Begriffe, die Sie oft sagen (optional). Sie gehen als Hinweis an das Transkriptionsmodell und als Glossar an das Bereinigungsmodell, damit es die repariert, die trotzdem falsch herauskommen.",
"No dictation history yet.": "Noch kein Diktatverlauf.",
"No matches": "Keine Treffer",
"No meetings yet.": "Noch keine Meetings.",
"No readings yet.": "Noch nichts vorgelesen.",
"Not enough disk space for the local model.": "Nicht genug Speicherplatz für das lokale Modell.",
"Nvidia GPU was requested, but no usable CUDA device was found. Check the driver and the CUDA runtime, or switch the device back to Automatic.": "Nvidia-GPU wurde angefordert, aber kein nutzbares CUDA-Gerät gefunden. Prüfen Sie den Treiber und die CUDA-Runtime, oder stellen Sie das Gerät zurück auf Automatisch.",
"Off by default: Claude reads through “erm” and “you know” without help, and cleanup costs an API call and a second or two.": "Standardmäßig aus: Claude liest über „ähm“ und „weißt du“ von selbst hinweg, und Bereinigung kostet einen API-Aufruf und ein, zwei Sekunden.",
"Once the history passes this many entries, the oldest one is dropped every time a new one arrives. Set it to 0 to keep everything.": "Sobald der Verlauf so viele Einträge überschreitet, wird bei jedem neuen der älteste verworfen. Auf 0 setzen, um alles zu behalten.",
"PDF reading needs pymupdf.": "PDF-Vorlesen benötigt pymupdf.",
"Play automatically when ready": "Automatisch abspielen, wenn bereit",
"Prefixes every chunk with [mm:ss], so the transcript can be saved as subtitles (.srt).": "Stellt jedem Abschnitt [mm:ss] voran, sodass das Transkript als Untertitel (.srt) gespeichert werden kann.",
"Read Turkish text aloud with a small local voice.": "Türkischen Text mit einer kleinen lokalen Stimme vorlesen.",
"Read aloud": "Vorlesen",
"Read-selection shortcut": "Kürzel zum Vorlesen der Auswahl",
"Reading aloud": "Vorlesen",
"Reading file {done} of {total}: {name}": "Datei {done} von {total} wird vorgelesen: {name}",
"Reading finished: {name}": "Vorlesen beendet: {name}",
"Reading part {done} of {total}…": "Abschnitt {done} von {total} wird vorgelesen…",
"Reading stopped.": "Vorlesen gestoppt.",
"Reading the capture…": "Bildschirmfoto wird gelesen…",
"Reading the selection…": "Auswahl wird vorgelesen…",
"Recent": "Zuletzt",
"Recent readings": "Zuletzt vorgelesen",
"Recording saved. The previous meeting is still being written up, so start this one from Settings → Meeting when it is done.": "Aufnahme gespeichert. Das vorherige Meeting wird noch ausgearbeitet, starten Sie dieses daher unter Einstellungen → Meeting, wenn es fertig ist.",
"Recording…": "Aufnahme läuft…",
"Retrying connection…": "Verbindung wird erneut versucht…",
"Runs the cleanup model over the transcript before the minutes are written, keeping the timestamps and the speaker labels.": "Lässt das Bereinigungsmodell über das Transkript laufen, bevor das Protokoll geschrieben wird, und behält dabei Zeitstempel und Sprecherbezeichnungen.",
"Save audio": "Audio speichern",
"Save audio…": "Audio speichern…",
"Select": "Auswählen",
"Shortcut saved: {shortcut}\nKWin only reads this file at startup, so it will not fire until you log out and back in. To use it right away, turn on the built-in listener.": "Tastenkürzel gespeichert: {shortcut}\nKWin liest diese Datei nur beim Start, daher wird es erst nach Ab- und Anmelden ausgelöst. Um es sofort zu nutzen, aktivieren Sie den eingebauten Listener.",
"Smart removes filler words while you speak. Verbatim keeps every word, including fillers.": "Smart entfernt Füllwörter, während Sie sprechen. Verbatim behält jedes Wort, auch Füllwörter.",
"Speak": "Sprechen",
"Speech also has to rise {margin} dB above the recording's own noise floor, so this absolute floor rarely needs touching. Lower it if quiet speech gets dropped; raise it if noise still gets through.": "Sprache muss außerdem {margin} dB über dem eigenen Grundrauschen der Aufnahme liegen, daher muss diese absolute Schwelle selten angefasst werden. Senken Sie sie, wenn leise Sprache verloren geht; erhöhen Sie sie, wenn Rauschen noch durchkommt.",
"Speed": "Geschwindigkeit",
"Stop shortcut": "Stopp-Kürzel",
"System instruction given to the cleanup model. This is where you decide how much it may touch your words.": "Systemanweisung für das Bereinigungsmodell. Hier legen Sie fest, wie stark es an Ihren Wörtern rühren darf.",
"Text and PDF files": "Text- und PDF-Dateien",
"Text and PDF files to turn into audio, in order.": "Text- und PDF-Dateien, die nacheinander in Audio umgewandelt werden.",
"Text to read": "Vorlesetext",
"The Turkish text to read aloud.": "Der türkische Text, der vorgelesen wird.",
"The directory the command runs in, which decides which project's instructions and files it can see. Your own skills and services are there whichever one it is.": "Das Verzeichnis, in dem der Befehl läuft; es entscheidet, welche Anweisungen und Dateien eines Projekts er sieht. Ihre eigenen Skills und Dienste sind da, welches es auch ist.",
"The local engine needs {packages}. Install them automatically and continue with the setup?": "Die lokale Engine benötigt {packages}. Automatisch installieren und mit der Einrichtung fortfahren?",
"The recording stopped on its own; the sound device may have gone away. Keeping what was captured.": "Die Aufnahme wurde von selbst beendet; das Audiogerät ist möglicherweise verschwunden. Das Aufgezeichnete wird behalten.",
"There is no readable text.": "Es gibt keinen lesbaren Text.",
"This shortcut records the same way dictation does, but the transcript is not what gets pasted. It goes to an agent as a command, and what comes back is pasted instead: the answer to a question, or a sentence saying what was done. Claude Code and Codex run as the session you would have opened yourself, with your skills, your connected services and your account.": "Dieses Kürzel nimmt genauso auf wie das Diktat, aber eingefügt wird nicht das Transkript. Es geht als Befehl an einen Agenten, und eingefügt wird, was zurückkommt: die Antwort auf eine Frage oder ein Satz, der sagt, was getan wurde. Claude Code und Codex laufen als die Sitzung, die Sie selbst geöffnet hätten – mit Ihren Skills, Ihren verbundenen Diensten und Ihrem Konto.",
"Told to the agent alongside every command, on top of whatever your own configuration already says.": "Wird dem Agenten mit jedem Befehl mitgeteilt, zusätzlich zu dem, was Ihre eigene Konfiguration bereits sagt.",
"Translate dictation to English": "Diktat ins Englische übersetzen",
"Translating…": "Wird übersetzt…",
"Turkish text-to-speech on the Speak tab.": "Türkische Sprachausgabe im Tab Sprechen.",
"Unlike cleanup, this one is worth some thinking: it has to hold a whole meeting in its head and work out what was actually decided.": "Anders als die Bereinigung lohnt sich hier etwas Nachdenken: Es muss ein ganzes Meeting im Kopf halten und herausfinden, was wirklich beschlossen wurde.",
"Unsupported file type: {suffix}": "Nicht unterstützter Dateityp: {suffix}",
"Used instead when an audio or video file is cleaned up. It is written for subtitles: lines stay where they are, nothing is shortened, and misheard words are repaired from the context.": "Wird stattdessen verwendet, wenn eine Audio- oder Videodatei bereinigt wird. Es ist für Untertitel geschrieben: Zeilen bleiben, wo sie sind, nichts wird gekürzt, und falsch Gehörtes wird aus dem Kontext korrigiert.",
"Verifying files…": "Dateien werden geprüft…",
"Voice engine needs onnxruntime: {error}": "Sprach-Engine benötigt onnxruntime: {error}",
"Voice model download failed.": "Download des Stimmmodells fehlgeschlagen.",
"Voice model ready.": "Stimmmodell bereit.",
"Wear headphones if you can. Through speakers your microphone hears the other side as well, and although a line that lands on both channels at once is dropped again, the repair is never as clean as not needing it.": "Tragen Sie möglichst Kopfhörer. Über Lautsprecher hört Ihr Mikrofon auch die Gegenseite, und obwohl eine Zeile, die gleichzeitig auf beiden Kanälen landet, wieder verworfen wird, ist die Reparatur nie so sauber, wie wenn man sie gar nicht bräuchte.",
"With its own rules, under Cleanup rules: written for subtitles, so the lines keep their place and nothing is shortened.": "Mit eigenen Regeln, unter Bereinigungsregeln: für Untertitel geschrieben, damit die Zeilen ihren Platz behalten und nichts gekürzt wird.",
"Works the moment you save — no logout needed. The key does not reach the focused application.": "Wirkt sofort beim Speichern — kein Abmelden nötig. Die Taste erreicht die fokussierte Anwendung nicht.",
"Your next dictation appears here.": "Ihr nächstes Diktat erscheint hier.",
"cancelled": "abgebrochen",
"{binary} is not on your PATH, so this cannot run yet. Install it, or pick another one above.": "{binary} ist nicht in Ihrem PATH, daher kann dies noch nicht laufen. Installieren Sie es, oder wählen Sie oben ein anderes.",
"{binary} not found. Install it, or pick another provider under Settings → Agent.": "{binary} nicht gefunden. Installieren Sie es, oder wählen Sie unter Einstellungen → Agent einen anderen Anbieter.",
"{done} / {total} · {speed}/s · Remaining: {eta}": "{done} / {total} · {speed}/s · Verbleibend: {eta}",
"{error}\n\nThe recording has been kept. Settings → Meeting can try again.": "{error}\n\nDie Aufnahme wurde behalten. Einstellungen → Meeting kann es erneut versuchen.",
"{message} ({action})": "{message} ({action})",
"{name} is installed ({size}) and ready. GPU support ({cuda_size}) can be downloaded; until then the model runs on CPU.": "{name} ist installiert ({size}) und bereit. GPU-Unterstützung ({cuda_size}) kann heruntergeladen werden; bis dahin läuft das Modell auf der CPU.",
"{name} is not downloaded yet — {size}. Downloaded once, it works offline after that.": "{name} ist noch nicht heruntergeladen — {size}. Einmal heruntergeladen, funktioniert es danach offline.",
"{seconds} s": "{seconds} s",
"{shortcut} is also used by:\n\n{list}\n\nInstall anyway?": "{shortcut} wird auch verwendet von:\n\n{list}\n\nTrotzdem installieren?",
}


