RU7 = {
"A command still running after this is given up on. The tray menu can stop one earlier.": "Команда, которая всё ещё выполняется после этого срока, отменяется. Меню трея может остановить её раньше.",
"A meeting is recorded from two devices at once: your microphone and whatever comes out of your speakers. Nothing has to guess who was speaking, because the two never share a channel.": "Встреча записывается с двух устройств одновременно: вашего микрофона и того, что выходит из динамиков. Ничему не нужно угадывать, кто говорил, потому что эти два никогда не делят канал.",
"A name like “sonnet” always means the newest model of that line. Opus thinks harder and answers slower, which is felt here more than anywhere else: you are standing in front of the screen.": "Имя вроде «sonnet» всегда означает самую новую модель этой линейки. Opus думает больше и отвечает медленнее, и здесь это заметнее, чем где-либо: вы стоите перед экраном.",
"A run that fails keeps its recording either way, so it can be tried again from the Meeting tab. This is about the ones that worked.": "Неудачный запуск в любом случае сохраняет запись, поэтому его можно повторить на вкладке «Встреча». Речь здесь об удачных.",
"Academic English": "Академический английский",
"Add an API key to use cloud models.": "Добавьте API-ключ, чтобы использовать облачные модели.",
"Add files…": "Добавить файлы…",
"Already reading…": "Уже идёт чтение…",
"Audio export failed: {error}": "Не удалось экспортировать аудио: {error}",
"Audio files": "Аудиофайлы",
"Audio files saved from this tab.": "Аудиофайлы, сохранённые с этой вкладки.",
"Audio output timed out.": "Истекло время ожидания аудиовыхода.",
"Audio stays on this computer. Cleanup is off; the raw transcript is used.": "Аудио остаётся на этом компьютере. Очистка выключена; используется необработанный транскрипт.",
"Audio stays on this computer. Cleanup sends the text to Gemini when enabled.": "Аудио остаётся на этом компьютере. Очистка отправляет текст в Gemini, когда включена.",
"Automatic uses the Nvidia GPU when its driver and CUDA runtime answer, otherwise the CPU. Forcing Nvidia GPU fails with a clear message when CUDA is missing instead of silently using the CPU.": "Автоматически использует GPU Nvidia, когда отвечают драйвер и среда CUDA, иначе CPU. Принудительный выбор GPU Nvidia завершается понятным сообщением, когда CUDA отсутствует, вместо тихого перехода на CPU.",
"Calculating…": "Вычисление…",
"Checking local speech device…": "Проверка локального речевого устройства…",
"Clear list": "Очистить список",
"Commands within this long of each other are one conversation, so “and move that to Thursday” knows what “that” is. After it, the next command starts fresh.": "Команды с таким интервалом — один разговор, поэтому «и перенеси это на четверг» знает, что такое «это». После него следующая команда начинается с чистого листа.",
"Connecting…": "Подключение…",
"Convert all to audio": "Преобразовать всё в аудио",
"Convert to audio and read": "Преобразовать в аудио и прочитать",
"Copied raw, cleanup failed: {error}": "Скопирован необработанный текст, очистка не удалась: {error}",
"Could not check the local speech device.": "Не удалось проверить локальное речевое устройство.",
"Could not read the selection.": "Не удалось прочитать выделенное.",
"Could not work out which speaker output to record. Pick one in Settings → Meeting.": "Не удалось определить, какой выход динамиков записывать. Выберите его в Настройки → Встреча.",
"Default format": "Формат по умолчанию",
"Default speed": "Скорость по умолчанию",
"Delete the downloaded {name} model? {size} goes back to the disk. Nothing else is touched.": "Удалить скачанную модель {name}? {size} вернётся на диск. Больше ничего не затрагивается.",
"Download stopped. Press Download to resume.": "Скачивание остановлено. Нажмите Скачать, чтобы продолжить.",
"Downloading the Turkish voice model (~34 MB)…": "Скачивание турецкой голосовой модели (~34 МБ)…",
"Downloads on first read (~34 MB).": "Скачивается при первом чтении (~34 МБ).",
"Everyone on the far end shares one label: they reach you as a single mixed signal. The names go to the transcription model so they come out spelled right, and to the minutes, which may use one for a line only when the conversation itself makes clear who was speaking.": "Все на другом конце линии получают одну метку: до вас они доходят как единый смешанный сигнал. Имена передаются модели транскрипции, чтобы они писались правильно, и в протокол, который может использовать имя для реплики, только если из самого разговора ясно, кто говорит.",
"Files": "Файлы",
"Format": "Формат",
"GPU support ({size}) is not installed yet. Download it first, then the {name} model? Answering No downloads only the model for CPU use.": "Поддержка GPU ({size}) ещё не установлена. Сначала скачать её, затем модель {name}? Ответ «Нет» скачает только модель для работы на CPU.",
"GPU support is not downloaded yet. Install it from Settings, Speech to text, or switch the device to Automatic.": "Поддержка GPU ещё не скачана. Установите её в Настройки → Речь в текст или переключите устройство на Автоматически.",
"Game English": "Игровой английский",
"How long a thinking model may reason before it answers. Cleanup is a light job, so more thinking mostly costs time and tokens. Models that cannot think ignore this.": "Сколько думающая модель может рассуждать перед ответом. Очистка — лёгкая задача, поэтому лишние размышления в основном тратят время и токены. Модели, которые не умеют думать, это игнорируют.",
"How the sound wave is drawn on the recording indicator. Spectrum and Capsules glow as you speak louder; Wave is a single flowing line.": "Как звуковая волна рисуется на индикаторе записи. Спектр и Капсулы светятся ярче, когда вы говорите громче; Волна — одна плавная линия.",
"Keep audio files (%LOCALAPPDATA%\\WordArc\\recordings)": "Хранить аудиофайлы (%LOCALAPPDATA%\\WordArc\\recordings)",
"Live uses {model}; it cannot be changed. The model under Transcript cleanup tidies the text afterwards.": "Вживую использует {model}; это нельзя изменить. Модель в разделе Очистка транскрипта приводит текст в порядок после этого.",
"Local transcribes on this computer and sends no audio anywhere. Cloud and Live use Gemini and need an API key: Cloud types up a recording after it ends, Live streams your speech as you speak and shows the words while you are still talking.": "Локально распознаёт на этом компьютере и никуда не отправляет аудио. Облако и Вживую используют Gemini и требуют API-ключ: Облако расшифровывает запись после её окончания, Вживую передаёт вашу речь по мере говорения и показывает слова, пока вы ещё говорите.",
"Measured on Turkish dictation. base is quick and the smallest download; small is in between; large-v3-turbo reads hardest audio most reliably and never invents a closing sentence.": "Измерено на турецкой диктовке. base — быстрая и самая маленькая загрузка; small — промежуточный вариант; large-v3-turbo надёжнее всего распознаёт самый сложный звук и никогда не придумывает завершающее предложение.",
"Meeting minutes and transcripts are stored as readable text files under %LOCALAPPDATA%\\WordArc\\meetings.": "Протоколы встреч и транскрипты хранятся как читаемые текстовые файлы в %LOCALAPPDATA%\\WordArc\\meetings.",
"Model download needs huggingface_hub: {error}": "Для загрузки модели нужен huggingface_hub: {error}",
"Model ready: {name}": "Модель готова: {name}",
"Model status": "Состояние модели",
"More thinking is slower, and you are standing in front of the screen while it happens. Worth it for a job that has to be worked out rather than looked up.": "Больше размышлений — медленнее, и всё это время вы стоите перед экраном. Оправдано для задачи, которую нужно продумать, а не найти.",
"Names and terms you say often (optional). They go to the transcription model as a hint, and to the cleanup model as a glossary, so it can repair the ones that still come out wrong.": "Имена и термины, которые вы часто произносите (необязательно). Они передаются модели транскрипции как подсказка, а модели очистки — как глоссарий, чтобы она исправляла те, что всё ещё выходят неверно.",
"No dictation history yet.": "Истории диктовки пока нет.",
"No matches": "Совпадений нет",
"No meetings yet.": "Встреч пока нет.",
"No readings yet.": "Чтений пока нет.",
"Not enough disk space for the local model.": "Недостаточно места на диске для локальной модели.",
"Nvidia GPU was requested, but no usable CUDA device was found. Check the driver and the CUDA runtime, or switch the device back to Automatic.": "Запрошен GPU Nvidia, но пригодное устройство CUDA не найдено. Проверьте драйвер и среду CUDA или верните устройство на «Автоматически».",
"Off by default: Claude reads through “erm” and “you know” without help, and cleanup costs an API call and a second or two.": "По умолчанию выключено: Claude и без этого читает сквозь «эээ» и «ну знаешь», а очистка стоит один вызов API и секунду-другую.",
"Once the history passes this many entries, the oldest one is dropped every time a new one arrives. Set it to 0 to keep everything.": "Когда история превысит это число записей, самая старая удаляется при каждом появлении новой. Установите 0, чтобы хранить всё.",
"PDF reading needs pymupdf.": "Для чтения PDF нужен pymupdf.",
"Play automatically when ready": "Воспроизводить автоматически, когда готово",
"Prefixes every chunk with [mm:ss], so the transcript can be saved as subtitles (.srt).": "Добавляет к каждому фрагменту префикс [mm:ss], чтобы транскрипт можно было сохранить как субтитры (.srt).",
"Read Turkish text aloud with a small local voice.": "Читать турецкий текст вслух небольшим локальным голосом.",
"Read aloud": "Читать вслух",
"Read-selection shortcut": "Клавиша чтения выделенного",
"Reading aloud": "Чтение вслух",
"Reading file {done} of {total}: {name}": "Чтение файла {done} из {total}: {name}",
"Reading finished: {name}": "Чтение завершено: {name}",
"Reading part {done} of {total}…": "Чтение части {done} из {total}…",
"Reading stopped.": "Чтение остановлено.",
"Reading the capture…": "Чтение снимка…",
"Reading the selection…": "Чтение выделенного…",
"Recent": "Последние",
"Recent readings": "Последние чтения",
"Recording saved. The previous meeting is still being written up, so start this one from Settings → Meeting when it is done.": "Запись сохранена. Предыдущая встреча ещё оформляется, поэтому запустите эту из Настройки → Встреча, когда она будет готова.",
"Recording…": "Запись…",
"Retrying connection…": "Повторное подключение…",
"Runs the cleanup model over the transcript before the minutes are written, keeping the timestamps and the speaker labels.": "Прогоняет модель очистки по транскрипту перед составлением протокола, сохраняя метки времени и метки говорящих.",
"Save audio": "Сохранить аудио",
"Save audio…": "Сохранить аудио…",
"Select": "Выбрать",
"Shortcut saved: {shortcut}\nKWin only reads this file at startup, so it will not fire until you log out and back in. To use it right away, turn on the built-in listener.": "Клавиша сохранена: {shortcut}\nKWin читает этот файл только при запуске, поэтому она не сработает до выхода и повторного входа. Чтобы пользоваться сразу, включите встроенный слушатель.",
"Smart removes filler words while you speak. Verbatim keeps every word, including fillers.": "Умный убирает слова-заполнители по мере речи. Дословно сохраняет каждое слово, включая заполнители.",
"Speak": "Озвучить",
"Speech also has to rise {margin} dB above the recording's own noise floor, so this absolute floor rarely needs touching. Lower it if quiet speech gets dropped; raise it if noise still gets through.": "Речь также должна превышать собственный шумовой порог записи на {margin} дБ, поэтому этот абсолютный порог трогать почти не нужно. Снизьте его, если тихая речь отбрасывается; повысьте, если шум всё ещё проходит.",
"Speed": "Скорость",
"Stop shortcut": "Клавиша остановки",
"System instruction given to the cleanup model. This is where you decide how much it may touch your words.": "Системная инструкция для модели очистки. Здесь вы решаете, насколько сильно она может вмешиваться в ваши слова.",
"Text and PDF files": "Текстовые файлы и PDF",
"Text and PDF files to turn into audio, in order.": "Текстовые файлы и PDF для преобразования в аудио, по порядку.",
"Text to read": "Текст для чтения",
"The Turkish text to read aloud.": "Турецкий текст для чтения вслух.",
"The directory the command runs in, which decides which project's instructions and files it can see. Your own skills and services are there whichever one it is.": "Каталог, в котором выполняется команда; он определяет, какие инструкции и файлы проекта она видит. Ваши собственные навыки и сервисы есть там, какой бы он ни был.",
"The local engine needs {packages}. Install them automatically and continue with the setup?": "Локальному движку нужны {packages}. Установить их автоматически и продолжить настройку?",
"The recording stopped on its own; the sound device may have gone away. Keeping what was captured.": "Запись остановилась сама; возможно, звуковое устройство пропало. Сохраняем записанное.",
"There is no readable text.": "Читаемого текста нет.",
"This shortcut records the same way dictation does, but the transcript is not what gets pasted. It goes to an agent as a command, and what comes back is pasted instead: the answer to a question, or a sentence saying what was done. Claude Code and Codex run as the session you would have opened yourself, with your skills, your connected services and your account.": "Эта клавиша записывает так же, как диктовка, но вставляется не транскрипт. Он уходит агенту как команда, а вместо него вставляется ответ: ответ на вопрос или фраза о том, что сделано. Claude Code и Codex работают как сессия, которую вы открыли бы сами, — с вашими навыками, подключёнными сервисами и вашим аккаунтом.",
"Told to the agent alongside every command, on top of whatever your own configuration already says.": "Сообщается агенту вместе с каждой командой, сверх того, что уже говорит ваша конфигурация.",
"Translate dictation to English": "Переводить диктовку на английский",
"Translating…": "Перевод…",
"Turkish text-to-speech on the Speak tab.": "Турецкий синтез речи на вкладке «Озвучить».",
"Unlike cleanup, this one is worth some thinking: it has to hold a whole meeting in its head and work out what was actually decided.": "В отличие от очистки, здесь стоит подумать: нужно удержать в голове всю встречу и понять, что на самом деле было решено.",
"Unsupported file type: {suffix}": "Неподдерживаемый тип файла: {suffix}",
"Used instead when an audio or video file is cleaned up. It is written for subtitles: lines stay where they are, nothing is shortened, and misheard words are repaired from the context.": "Используется вместо неё, когда очищается аудио- или видеофайл. Она написана для субтитров: строки остаются на месте, ничего не сокращается, а неверно услышанные слова исправляются по контексту.",
"Verifying files…": "Проверка файлов…",
"Voice engine needs onnxruntime: {error}": "Голосовому движку нужен onnxruntime: {error}",
"Voice model download failed.": "Не удалось загрузить голосовую модель.",
"Voice model ready.": "Голосовая модель готова.",
"Wear headphones if you can. Through speakers your microphone hears the other side as well, and although a line that lands on both channels at once is dropped again, the repair is never as clean as not needing it.": "По возможности наденьте наушники. Через динамики микрофон слышит и другую сторону, и хотя реплика, попавшая сразу в оба канала, снова отбрасывается, исправление никогда не бывает таким же чистым, как его отсутствие.",
"With its own rules, under Cleanup rules: written for subtitles, so the lines keep their place and nothing is shortened.": "Со своими правилами, в разделе Правила очистки: написано для субтитров, поэтому строки сохраняют своё место и ничего не сокращается.",
"Works the moment you save — no logout needed. The key does not reach the focused application.": "Работает сразу после сохранения — выходить из системы не нужно. Клавиша не доходит до активного приложения.",
"Your next dictation appears here.": "Здесь появится ваша следующая диктовка.",
"cancelled": "отменено",
"{binary} is not on your PATH, so this cannot run yet. Install it, or pick another one above.": "{binary} нет в вашем PATH, поэтому это пока не запустится. Установите его или выберите другой выше.",
"{binary} not found. Install it, or pick another provider under Settings → Agent.": "{binary} не найден. Установите его или выберите другого провайдера в Настройки → Агент.",
"{done} / {total} · {speed}/s · Remaining: {eta}": "{done} / {total} · {speed}/с · Осталось: {eta}",
"{error}\n\nThe recording has been kept. Settings → Meeting can try again.": "{error}\n\nЗапись сохранена. Настройки → Встреча может попробовать снова.",
"{message} ({action})": "{message} ({action})",
"{name} is installed ({size}) and ready. GPU support ({cuda_size}) can be downloaded; until then the model runs on CPU.": "{name} установлена ({size}) и готова. Можно загрузить поддержку GPU ({cuda_size}); до тех пор модель работает на CPU.",
"{name} is not downloaded yet — {size}. Downloaded once, it works offline after that.": "{name} ещё не загружена — {size}. После однократной загрузки она работает оффлайн.",
"{seconds} s": "{seconds} с",
"{shortcut} is also used by:\n\n{list}\n\nInstall anyway?": "{shortcut} также используется:\n\n{list}\n\nВсё равно установить?",
}


