PL7 = {
"A command still running after this is given up on. The tray menu can stop one earlier.": "Polecenie wciąż działające po tym czasie jest porzucane. Menu zasobnika może zatrzymać je wcześniej.",
"A meeting is recorded from two devices at once: your microphone and whatever comes out of your speakers. Nothing has to guess who was speaking, because the two never share a channel.": "Spotkanie jest nagrywane z dwóch urządzeń naraz: Twojego mikrofonu i tego, co wychodzi z głośników. Nic nie musi zgadywać, kto mówił, bo te dwa nigdy nie dzielą kanału.",
"A name like “sonnet” always means the newest model of that line. Opus thinks harder and answers slower, which is felt here more than anywhere else: you are standing in front of the screen.": "Nazwa taka jak „sonnet” zawsze oznacza najnowszy model z tej serii. Opus myśli więcej i odpowiada wolniej, co odczuwa się tu bardziej niż gdziekolwiek: stoisz przed ekranem.",
"A run that fails keeps its recording either way, so it can be tried again from the Meeting tab. This is about the ones that worked.": "Nieudany przebieg i tak zachowuje swoje nagranie, więc można spróbować ponownie z zakładki Spotkanie. Tu chodzi o te, które się udały.",
"Academic English": "Angielski akademicki",
"Add an API key to use cloud models.": "Dodaj klucz API, aby używać modeli chmurowych.",
"Add files…": "Dodaj pliki…",
"Already reading…": "Już trwa czytanie…",
"Audio export failed: {error}": "Eksport dźwięku nie powiódł się: {error}",
"Audio files": "Pliki audio",
"Audio files saved from this tab.": "Pliki audio zapisane z tej karty.",
"Audio output timed out.": "Przekroczono limit czasu wyjścia audio.",
"Audio stays on this computer. Cleanup is off; the raw transcript is used.": "Dźwięk pozostaje na tym komputerze. Czyszczenie jest wyłączone; używana jest surowa transkrypcja.",
"Audio stays on this computer. Cleanup sends the text to Gemini when enabled.": "Dźwięk pozostaje na tym komputerze. Czyszczenie wysyła tekst do Gemini, gdy jest włączone.",
"Automatic uses the Nvidia GPU when its driver and CUDA runtime answer, otherwise the CPU. Forcing Nvidia GPU fails with a clear message when CUDA is missing instead of silently using the CPU.": "Automatyczny używa GPU Nvidia, gdy odpowiadają jego sterownik i środowisko CUDA, w przeciwnym razie CPU. Wymuszenie GPU Nvidia kończy się jasnym komunikatem, gdy brakuje CUDA, zamiast po cichu używać CPU.",
"Calculating…": "Obliczanie…",
"Checking local speech device…": "Sprawdzanie lokalnego urządzenia mowy…",
"Clear list": "Wyczyść listę",
"Commands within this long of each other are one conversation, so “and move that to Thursday” knows what “that” is. After it, the next command starts fresh.": "Polecenia wypowiedziane w tym odstępie to jedna rozmowa, dzięki czemu „i przenieś to na czwartek” wie, czym jest „to”. Po nim następne polecenie zaczyna od nowa.",
"Connecting…": "Łączenie…",
"Convert all to audio": "Konwertuj wszystko na audio",
"Convert to audio and read": "Konwertuj na audio i czytaj",
"Copied raw, cleanup failed: {error}": "Skopiowano surowe, czyszczenie nie powiodło się: {error}",
"Could not check the local speech device.": "Nie można sprawdzić lokalnego urządzenia mowy.",
"Could not read the selection.": "Nie można odczytać zaznaczenia.",
"Could not work out which speaker output to record. Pick one in Settings → Meeting.": "Nie udało się ustalić, które wyjście głośnikowe nagrywać. Wybierz je w Ustawienia → Spotkanie.",
"Default format": "Domyślny format",
"Default speed": "Domyślna prędkość",
"Delete the downloaded {name} model? {size} goes back to the disk. Nothing else is touched.": "Usunąć pobrany model {name}? {size} wróci na dysk. Nic innego nie zostanie ruszone.",
"Download stopped. Press Download to resume.": "Pobieranie zatrzymane. Naciśnij Pobierz, aby wznowić.",
"Downloading the Turkish voice model (~34 MB)…": "Pobieranie tureckiego modelu głosu (~34 MB)…",
"Downloads on first read (~34 MB).": "Pobierane przy pierwszym czytaniu (~34 MB).",
"Everyone on the far end shares one label: they reach you as a single mixed signal. The names go to the transcription model so they come out spelled right, and to the minutes, which may use one for a line only when the conversation itself makes clear who was speaking.": "Wszyscy po drugiej stronie dzielą jedną etykietę: docierają do Ciebie jako jeden zmieszany sygnał. Nazwy trafiają do modelu transkrypcji, aby były zapisane poprawnie, oraz do protokołu, który może użyć jednej z nich w wierszu tylko wtedy, gdy sama rozmowa jasno pokazuje, kto mówił.",
"Files": "Pliki",
"Format": "Format",
"GPU support ({size}) is not installed yet. Download it first, then the {name} model? Answering No downloads only the model for CPU use.": "Wsparcie GPU ({size}) nie jest jeszcze zainstalowane. Pobrać je najpierw, a potem model {name}? Odpowiedź Nie pobiera tylko model do pracy na CPU.",
"GPU support is not downloaded yet. Install it from Settings, Speech to text, or switch the device to Automatic.": "Wsparcie GPU nie jest jeszcze pobrane. Zainstaluj je w Ustawieniach, Mowa na tekst, albo przełącz urządzenie na Automatyczny.",
"Game English": "Angielski w grach",
"How long a thinking model may reason before it answers. Cleanup is a light job, so more thinking mostly costs time and tokens. Models that cannot think ignore this.": "Jak długo model myślący może rozumować, zanim odpowie. Czyszczenie to lekkie zadanie, więc więcej myślenia przeważnie kosztuje czas i tokeny. Modele, które nie potrafią myśleć, ignorują to.",
"How the sound wave is drawn on the recording indicator. Spectrum and Capsules glow as you speak louder; Wave is a single flowing line.": "Jak fala dźwiękowa jest rysowana na wskaźniku nagrywania. Spectrum i Capsules świecą mocniej, gdy mówisz głośniej; Wave to jedna płynąca linia.",
"Keep audio files (%LOCALAPPDATA%\\WordArc\\recordings)": "Zachowaj pliki audio (%LOCALAPPDATA%\\WordArc\\recordings)",
"Live uses {model}; it cannot be changed. The model under Transcript cleanup tidies the text afterwards.": "Na żywo używa {model}; tego nie można zmienić. Model w sekcji Czyszczenie transkrypcji porządkuje tekst potem.",
"Local transcribes on this computer and sends no audio anywhere. Cloud and Live use Gemini and need an API key: Cloud types up a recording after it ends, Live streams your speech as you speak and shows the words while you are still talking.": "Lokalny transkrybuje na tym komputerze i nigdzie nie wysyła dźwięku. Chmura i Na żywo używają Gemini i wymagają klucza API: Chmura spisuje nagranie po jego zakończeniu, Na żywo przesyła Twoją mowę, gdy mówisz, i pokazuje słowa, kiedy jeszcze mówisz.",
"Measured on Turkish dictation. base is quick and the smallest download; small is in between; large-v3-turbo reads hardest audio most reliably and never invents a closing sentence.": "Mierzone na tureckim dyktowaniu. base jest szybki i to najmniejsze pobieranie; small jest pośrodku; large-v3-turbo najpewniej czyta najtrudniejszy dźwięk i nigdy nie wymyśla zdania zamykającego.",
"Meeting minutes and transcripts are stored as readable text files under %LOCALAPPDATA%\\WordArc\\meetings.": "Protokoły spotkań i transkrypcje są przechowywane jako czytelne pliki tekstowe w %LOCALAPPDATA%\\WordArc\\meetings.",
"Model download needs huggingface_hub: {error}": "Pobieranie modelu wymaga huggingface_hub: {error}",
"Model ready: {name}": "Model gotowy: {name}",
"Model status": "Stan modelu",
"More thinking is slower, and you are standing in front of the screen while it happens. Worth it for a job that has to be worked out rather than looked up.": "Więcej myślenia to wolniejsze działanie, a Ty w tym czasie stoisz przed ekranem. Warto przy zadaniu, które trzeba przemyśleć, a nie wyszukać.",
"Names and terms you say often (optional). They go to the transcription model as a hint, and to the cleanup model as a glossary, so it can repair the ones that still come out wrong.": "Nazwy i terminy, które mówisz często (opcjonalnie). Trafiają do modelu transkrypcji jako podpowiedź, a do modelu czyszczenia jako słownik, żeby mógł poprawić te, które nadal wychodzą źle.",
"No dictation history yet.": "Brak historii dyktowania.",
"No matches": "Brak wyników",
"No meetings yet.": "Brak spotkań.",
"No readings yet.": "Nic jeszcze nie odczytano.",
"Not enough disk space for the local model.": "Za mało miejsca na dysku dla modelu lokalnego.",
"Nvidia GPU was requested, but no usable CUDA device was found. Check the driver and the CUDA runtime, or switch the device back to Automatic.": "Zażądano GPU Nvidia, ale nie znaleziono użytecznego urządzenia CUDA. Sprawdź sterownik i środowisko CUDA albo przełącz urządzenie z powrotem na Automatyczny.",
"Off by default: Claude reads through “erm” and “you know” without help, and cleanup costs an API call and a second or two.": "Domyślnie wyłączone: Claude sam przechodzi przez „eee” i „wiesz”, a czyszczenie kosztuje wywołanie API i sekundę czy dwie.",
"Once the history passes this many entries, the oldest one is dropped every time a new one arrives. Set it to 0 to keep everything.": "Gdy historia przekroczy tyle wpisów, przy każdym nowym najstarszy jest usuwany. Ustaw 0, aby zachować wszystko.",
"PDF reading needs pymupdf.": "Czytanie PDF wymaga pymupdf.",
"Play automatically when ready": "Odtwarzaj automatycznie, gdy gotowe",
"Prefixes every chunk with [mm:ss], so the transcript can be saved as subtitles (.srt).": "Dodaje [mm:ss] przed każdym fragmentem, aby transkrypcję można było zapisać jako napisy (.srt).",
"Read Turkish text aloud with a small local voice.": "Czytaj turecki tekst na głos małym lokalnym głosem.",
"Read aloud": "Czytaj na głos",
"Read-selection shortcut": "Skrót czytania zaznaczenia",
"Reading aloud": "Czytanie na głos",
"Reading file {done} of {total}: {name}": "Czytanie pliku {done} z {total}: {name}",
"Reading finished: {name}": "Czytanie zakończone: {name}",
"Reading part {done} of {total}…": "Czytanie części {done} z {total}…",
"Reading stopped.": "Czytanie zatrzymane.",
"Reading the capture…": "Czytanie przechwycenia…",
"Reading the selection…": "Czytanie zaznaczenia…",
"Recent": "Ostatnie",
"Recent readings": "Ostatnie czytania",
"Recording saved. The previous meeting is still being written up, so start this one from Settings → Meeting when it is done.": "Nagranie zapisane. Poprzednie spotkanie jest jeszcze spisywane, więc uruchom to z Ustawienia → Spotkanie, gdy będzie gotowe.",
"Recording…": "Nagrywanie…",
"Retrying connection…": "Ponawianie połączenia…",
"Runs the cleanup model over the transcript before the minutes are written, keeping the timestamps and the speaker labels.": "Przepuszcza transkrypcję przez model czyszczenia, zanim powstanie protokół, zachowując znaczniki czasu i etykiety mówców.",
"Save audio": "Zapisz audio",
"Save audio…": "Zapisz audio…",
"Select": "Zaznacz",
"Shortcut saved: {shortcut}\nKWin only reads this file at startup, so it will not fire until you log out and back in. To use it right away, turn on the built-in listener.": "Skrót zapisany: {shortcut}\nKWin czyta ten plik tylko przy starcie, więc zadziała dopiero po wylogowaniu i ponownym zalogowaniu. Aby użyć go od razu, włącz wbudowany nasłuchiwacz.",
"Smart removes filler words while you speak. Verbatim keeps every word, including fillers.": "Inteligentny usuwa słowa wypełniające, gdy mówisz. Dosłowny zachowuje każde słowo, łącznie z wypełniaczami.",
"Speak": "Mów",
"Speech also has to rise {margin} dB above the recording's own noise floor, so this absolute floor rarely needs touching. Lower it if quiet speech gets dropped; raise it if noise still gets through.": "Mowa musi też być o {margin} dB głośniejsza niż własny szum nagrania, więc ten bezwzględny próg rzadko wymaga ruszania. Obniż go, jeśli cicha mowa jest odrzucana; podnieś, jeśli hałas nadal przechodzi.",
"Speed": "Prędkość",
"Stop shortcut": "Skrót zatrzymania",
"System instruction given to the cleanup model. This is where you decide how much it may touch your words.": "Instrukcja systemowa dla modelu czyszczenia. Tutaj decydujesz, jak bardzo może ingerować w Twoje słowa.",
"Text and PDF files": "Pliki tekstowe i PDF",
"Text and PDF files to turn into audio, in order.": "Pliki tekstowe i PDF do zamiany na audio, po kolei.",
"Text to read": "Tekst do czytania",
"The Turkish text to read aloud.": "Turecki tekst do przeczytania na głos.",
"The directory the command runs in, which decides which project's instructions and files it can see. Your own skills and services are there whichever one it is.": "Katalog, w którym działa polecenie; decyduje, które instrukcje i pliki projektu widzi. Twoje własne umiejętności i usługi są tam niezależnie od tego, który to katalog.",
"The local engine needs {packages}. Install them automatically and continue with the setup?": "Lokalny silnik wymaga {packages}. Zainstalować je automatycznie i kontynuować konfigurację?",
"The recording stopped on its own; the sound device may have gone away. Keeping what was captured.": "Nagranie zatrzymało się samo; urządzenie dźwiękowe mogło zniknąć. Zachowuję to, co przechwycono.",
"There is no readable text.": "Nie ma czytelnego tekstu.",
"This shortcut records the same way dictation does, but the transcript is not what gets pasted. It goes to an agent as a command, and what comes back is pasted instead: the answer to a question, or a sentence saying what was done. Claude Code and Codex run as the session you would have opened yourself, with your skills, your connected services and your account.": "Ten skrót nagrywa tak samo jak dyktowanie, ale wklejany jest nie transkrypt. Trafia on do agenta jako polecenie, a wkleja się to, co wróci: odpowiedź na pytanie albo zdanie mówiące, co zrobiono. Claude Code i Codex działają jako sesja, którą sam byś otworzył — z Twoimi umiejętnościami, podłączonymi usługami i Twoim kontem.",
"Told to the agent alongside every command, on top of whatever your own configuration already says.": "Przekazywane agentowi przy każdym poleceniu, oprócz tego, co mówi już Twoja konfiguracja.",
"Translate dictation to English": "Tłumacz dyktowanie na angielski",
"Translating…": "Tłumaczenie…",
"Turkish text-to-speech on the Speak tab.": "Turecka synteza mowy na karcie Mów.",
"Unlike cleanup, this one is worth some thinking: it has to hold a whole meeting in its head and work out what was actually decided.": "W przeciwieństwie do czyszczenia tutaj warto dać trochę myślenia: musi utrzymać całe spotkanie w głowie i ustalić, co faktycznie zdecydowano.",
"Unsupported file type: {suffix}": "Nieobsługiwany typ pliku: {suffix}",
"Used instead when an audio or video file is cleaned up. It is written for subtitles: lines stay where they are, nothing is shortened, and misheard words are repaired from the context.": "Używana zamiast niej, gdy czyszczony jest plik audio lub wideo. Jest napisana pod napisy: linie zostają na miejscu, nic nie jest skracane, a źle usłyszane słowa są poprawiane z kontekstu.",
"Verifying files…": "Weryfikacja plików…",
"Voice engine needs onnxruntime: {error}": "Silnik głosu wymaga onnxruntime: {error}",
"Voice model download failed.": "Pobieranie modelu głosu nie powiodło się.",
"Voice model ready.": "Model głosu gotowy.",
"Wear headphones if you can. Through speakers your microphone hears the other side as well, and although a line that lands on both channels at once is dropped again, the repair is never as clean as not needing it.": "Noś słuchawki, jeśli możesz. Przez głośniki mikrofon słyszy też drugą stronę, a choć linia, która trafia na oba kanały naraz, jest znowu odrzucana, naprawa nigdy nie jest tak czysta jak jej brak.",
"With its own rules, under Cleanup rules: written for subtitles, so the lines keep their place and nothing is shortened.": "Z własnymi regułami, w Regułach czyszczenia: pisane pod napisy, więc linie zachowują swoje miejsce i nic nie jest skracane.",
"Works the moment you save — no logout needed. The key does not reach the focused application.": "Działa od razu po zapisaniu — bez wylogowania. Klawisz nie dociera do aktywnej aplikacji.",
"Your next dictation appears here.": "Twoje następne dyktowanie pojawi się tutaj.",
"cancelled": "anulowano",
"{binary} is not on your PATH, so this cannot run yet. Install it, or pick another one above.": "{binary} nie jest w Twoim PATH, więc to jeszcze nie zadziała. Zainstaluj go lub wybierz inny powyżej.",
"{binary} not found. Install it, or pick another provider under Settings → Agent.": "Nie znaleziono {binary}. Zainstaluj go lub wybierz innego dostawcę w Ustawienia → Agent.",
"{done} / {total} · {speed}/s · Remaining: {eta}": "{done} / {total} · {speed}/s · Pozostało: {eta}",
"{error}\n\nThe recording has been kept. Settings → Meeting can try again.": "{error}\n\nNagranie zachowane. Ustawienia → Spotkanie może spróbować ponownie.",
"{message} ({action})": "{message} ({action})",
"{name} is installed ({size}) and ready. GPU support ({cuda_size}) can be downloaded; until then the model runs on CPU.": "{name} jest zainstalowany ({size}) i gotowy. Wsparcie GPU ({cuda_size}) można pobrać; do tego czasu model działa na CPU.",
"{name} is not downloaded yet — {size}. Downloaded once, it works offline after that.": "{name} nie jest jeszcze pobrany — {size}. Po jednorazowym pobraniu działa offline.",
"{seconds} s": "{seconds} s",
"{shortcut} is also used by:\n\n{list}\n\nInstall anyway?": "{shortcut} jest też używany przez:\n\n{list}\n\nZainstalować mimo to?",
}


